WITH rows AS (SELECT CAST(key AS INTEGER) AS ord, json_extract(value,'$[0]') AS provider, json_extract(value,'$[1]') AS gpu, json_extract(value,'$[2]') AS before, json_extract(value,'$[3]') AS after FROM json_each(readfile('evidence/user-inputs.json'),'$.secondNote.rows')) SELECT ord AS 'order', provider, gpu, before, after, after*1.0/before-1.0 AS change, CASE provider WHEN 'Ornn' THEN '官方历史逐日已核实' WHEN 'Silicon Data' THEN '官网当前展示值吻合；区间历史待核实' WHEN 'Compute Desk' THEN '方法已核实；本期数值待核实' ELSE '来源、样本及日期待补' END AS verification FROM rows ORDER BY ord;
